const root = $input.first().json ?? {};
const body = (root.body && typeof root.body === 'object') ? root.body : root;

const allowed = new Set([
  'conversation.turn.completed',
  'purchase.intent',
  'handoff.requested',
  'notification.requested',
]);

const type = String(body?.type ?? '').trim();
const sessionId = String(body?.sessionId ?? '').trim();
const occurredAt = String(body?.occurredAt ?? '').trim();
const payload = (body?.payload && typeof body.payload === 'object' && !Array.isArray(body.payload))
  ? body.payload
  : {};

function reject(statusCode, code, message) {
  return [{
    json: {
      ok: false,
      accepted: false,
      statusCode,
      code,
      message,
      route: 'invalid',
      receivedType: type || null,
      sessionId: sessionId || null,
      receivedAt: new Date().toISOString(),
    }
  }];
}

if (!type) return reject(400, 'EVENT_TYPE_REQUIRED', 'type is required');
if (!allowed.has(type)) {
  return reject(422, 'EVENT_TYPE_NOT_SUPPORTED', `Unsupported event type: ${type}`);
}
if (!sessionId) return reject(400, 'SESSION_ID_REQUIRED', 'sessionId is required');
if (!occurredAt || Number.isNaN(Date.parse(occurredAt))) {
  return reject(400, 'OCCURRED_AT_INVALID', 'occurredAt must be a valid ISO date');
}

return [{
  json: {
    ok: true,
    accepted: true,
    statusCode: 202,
    code: 'EVENT_ACCEPTED',
    route: type,
    type,
    sessionId,
    occurredAt,
    payload,
    receivedAt: new Date().toISOString(),
  }
}];

return $input.all().map(item => ({
  json: {
    ...item.json,
    handledBy: '04A Conversation Turn Completed',
  }
}));
